#include <math.h>
struct point { double x, y; int id; };
int fib(int n) { return n < 2 ? n : fib(n-1) + fib(n-2); }
int apply(int (*f)(int), int n) { return f(n); }
double dist(struct point a, struct point b) {
  return sqrt((a.x-b.x)*(a.x-b.x) + (a.y-b.y)*(a.y-b.y));
}
int main(void) {
  struct point p = {1.5, 2.5, 7}, q = {4.5, 6.5, 9};
  int s = 0; int arr[5] = {1,2,3,4,5};
  for (int i = 0; i < 5; i++) s += arr[i];
  char buf[16]; int n = 0;
  while (n < 8) { buf[n++] = 'a' + n; } buf[n] = 0;
  printf("fib(20)=%d sum=%d dist=%.4f buf=%s id=%d\n",
         apply(fib, 20), s, dist(p, q), buf, p.id + q.id);
  return s == 15 && apply(fib, 20) == 6765 && p.id == 7 ? 0 : 1;
}
EOF
