cd /tmp && export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin && cat > tcomplex2.c <<'EOF'
struct point { double x, y; int id; };
int fib(int n) { return n < 2 ? n : fib(n-1) + fib(n-2); }
int apply(int (*f)(int), int n) { return f(n); }
double dist2(struct point a, struct point b) {
  double dx = a.x - b.x, dy = a.y - b.y;
  return dx*dx + dy*dy;
}
int main(void) {
  struct point p = {1.5, 2.5, 7}, q = {4.5, 6.5, 9};
  int s = 0; int arr[5] = {1,2,3,4,5};
  double d = 0.1, f = 1.5e3, e = 2.25;
  int ok = 1;
  for (int i = 0; i < 5; i++) s += arr[i];
  ok &= (s == 15);
  ok &= (apply(fib, 20) == 6765);
  ok &= (dist2(p, q) == 9.0 + 16.0);
  ok &= (d + f == 1500.1);
  ok &= (e * 4.0 == 9.0);
  ok &= (p.id + q.id == 16);
  switch (s % 3) { case 0: ok &= (s == 15); break; default: ok = 0; }
  return ok ? 0 : 1;
}
EOF
